@RunWith(MockitoJUnitRunner.class)
public class CheckSideEffects_visit_TriageGen1Test {

    private CheckSideEffects checker;

    @Mock private NodeTraversal t;
    @Mock private Compiler compiler;
    @Mock private Node n;
    @Mock private Node parent;
    @Mock private Node gramps;
    @Mock private Node nextNode;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        checker = new CheckSideEffects();
        // Note: Since problemNodes is likely private, we check results via compiler reports
        when(t.getCompiler()).thenReturn(compiler);
        when(compiler.report(any())).thenAnswer(invocation -> {
            // This allows us to verify if an error was reported
            return null;
        });
    }

    @Test
    public void testVisit_EmptyOrCommaNode_ReturnsImmediately() {
        when(n.isEmpty()).thenReturn(true);
        checker.visit(t, n, parent);
        verifyZeroInteractions(compiler);

        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(true);
        checker.visit(t, n, parent);
        verifyZeroInteractions(compiler);
    }

    @Test
    public void testVisit_NullParent_ReturnsImmediately() {
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        checker.visit(t, n, null);
        verifyZeroInteractions(compiler);
    }

    @Test
    public void testVisit_ParentIsComma_SpecialEvalCase() {
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        when(parent.getType()).thenReturn(Token.COMMA);
        when(parent.getParent()).thenReturn(gramps);
        when(gramps.isCall()).thenReturn(true);
        when(parent.getFirstChild()).thenReturn(parent); // parent == gramps.getFirstChild()
        when(n.getNext()).thenReturn(nextNode);
        when(nextNode.isName()).thenReturn(true);
        when(nextNode.getString()).thenReturn("eval");
        when(parent.getChildCount()).thenReturn(2);
        when(n == parent.getFirstChild()).thenReturn(true);

        checker.visit(t, n, parent);
        verifyZeroInteractions(compiler);
    }

    @Test
    public void testVisit_ParentIsComma_JSDocProtection() {
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        when(parent.getType()).thenReturn(Token.COMMA);
        when(parent.getParent()).thenReturn(gramps);
        when(n == parent.getLastChild()).thenReturn(true);

        // Mock ancestors to simulate JSDoc protection
        Node ancestor1 = mock(Node.class);
        when(ancestor1.getType()).thenReturn(Token.BLOCK);
        Node ancestor2 = mock(Node.class);
        when(ancestor2.getType()).thenReturn(Token.EXPR_RESULT);

        when(parent.getAncestors()).thenReturn(java.util.Arrays.asList(ancestor1, ancestor2));

        checker.visit(t, n, parent);
        verifyZeroInteractions(compiler);
    }

