    public void testVisit_UselessString_ReportsError() {
        // Setup to bypass early returns
        when(n.isEmpty()).thenReturn(false);
        when(n.isComma()).thenReturn(false);
        when(parent.getType()).thenReturn(Token.BLOCK);
        when(n == parent.getLastChild()).thenReturn(false);

        // Mock NodeUtil behavior via Node properties if possible, 
        // otherwise this test assumes NodeUtil is injectable or mockable.
        // Since NodeUtil is static, we assume standard behavior for this exercise.

